def build_markdown():
    text=(ROOT/'docs/FINAL_BUSINESS_PLAN.md').read_text()
    rows=model();y=rows[1]
    replacements={"{fmt(y1['fixed_opex_rub'])}":fmt(y['fixed_opex_rub']),'{fmt(PAYROLL_GROSS_ANNUAL)}':fmt(PAYROLL_GROSS_ANNUAL),'{fmt(PAYROLL_CONTRIBUTIONS_ANNUAL)}':fmt(PAYROLL_CONTRIBUTIONS_ANNUAL),'{fmt(PAYROLL_TOTAL_ANNUAL)}':fmt(PAYROLL_TOTAL_ANNUAL),'Не достигнута года':'не достигнута за 5 лет','3,68 / не достигнута за 5 лет':'3,68 года / не достигнута за 5 лет'}
    for a,b in replacements.items():text=text.replace(a,b)
    text=text.replace('Редакция 21.10.2026;','Редакция после brainstorming; ветка AgroVector_After_brainstorm;')
    status='\n**Редакционная граница:** исправлены представление расходов и расчет runway, добавлены ограничения и условия решений. Исходная экономика не подменена. Внешние источники ниже — унаследованные датированные снимки; нового юридического/рыночного подтверждения нет. Основной экспорт — `data/finance_corrected_brainstorm.json`; исторические файлы без суффикса — контрольная база.\n'
    text=text.replace('## 1. Резюме',status+'\n## 1. Резюме',1)
    # Attach each change within its original numbered section, not as a replacement for required models.
    for number,body in additions().items():
        pat=rf'(^## {number}\. [^\n]+\n)'
        text,n=re.subn(pat,lambda m:m[0]+'\n### Уточнение после brainstorming\n\n'+body+'\n',text,count=1,flags=re.M)
        assert n==1,number
    gates='''\n### Условия перехода к запуску\n\n| Gate | Требуемое доказательство | Ответственный | Статус |\n|---|---|---|---|\n| G0 Право и налоги | Применимый маршрут для полей/работ/оператора; налоговая карта и договор | Директор, юрист, бухгалтер | Внешняя проверка открыта |\n| G1 Покупатель | Конкретные объемы, цена, окна, приемка и оплата; не только интервью | Директор | Внешняя проверка открыта |\n| G2 Ресурс | Сопоставимые полные КП, команда, сервис и совместный календарь | Операционный руководитель | Внешняя проверка открыта |\n| G3 Экономика | Пересчет NPV, мощности и кассы на условиях G0–G2; согласованный буфер | Финансовый ответственный | Сценарии рассчитаны; реальные условия открыты |\n| G4 Ограниченный пилот | Допуск, протокол качества, полная себестоимость и фактическая оплата | Команда и клиент | Не проводился |\n| G5 Следующая инвестиционная редакция | Выбранные подтвержденные условия и согласованные лимиты обязательств | Директор/инвестор | Не утверждена |\n\n[ДОПУЩЕНИЕ] Нельзя принимать необратимые обязательства, если применимый gate не пройден. Кабинетные проверки и сбор КП могут идти параллельно; расходы требуют заранее согласованного лимита. Сама подготовка этой редакции не означает прохождения G0–G5. Матрица всех решений — `docs/CHANGE_DECISIONS_brainstorm.md`; детали расчетов — `docs/FINANCE_CORRECTED_brainstorm.md`.\n\n'''
    text=text.replace('## Sources',gates+'## Sources',1)
    assert '{fmt(' not in text
    (ROOT/'docs/FINAL_BUSINESS_PLAN_brainstorm.md').write_text(text)
    method=(ROOT/'docs/FINANCE_METHOD.md').read_text()
    method=method.replace('фиксированные 350 000 RUB/месяц','фиксированные '+fmt(y['fixed_opex_rub']/12)+' RUB/месяц')
    method=method.replace('Запуск из корня:', 'Исторический генератор контрольной базы (не запускать для исправленной редакции):')
    intro='\n**Исправленная параллельная редакция AgroVector_After_brainstorm.** Воспроизведение: `.venv/bin/python scripts/build_corrected_finance_brainstorm.py`. Базовые допущения сохранены; исправленный экспорт — `data/finance_corrected_brainstorm.json`. Методика ниже унаследована, внешние правовые и налоговые предпосылки не перепроверялись.\n\n'
    method=method.replace('## Статус данных и запуск',intro+'## Статус данных и запуск',1)
    reserve=rows[0]['reserve_funding_rub'];burn=y['fixed_opex_rub']/12
    negative=next(i for i in range(1,120) if reserve-i*burn<0)
    method=method.replace('## Слабые места',f'Первый отрицательный остаток без выручки: **{negative}-й месяц**, вычислен по `резерв − месяц × fixed/12 < 0`. Не относится к базовой кассе с апрельскими поступлениями. Сценарии мощности, аванса/отсрочки и условия запуска раскрыты в FINANCE_CORRECTED_brainstorm.md.\n\n## Слабые места',1)
    (ROOT/'docs/FINANCE_METHOD_brainstorm.md').write_text(method)
    return text

def build_word(text):
    # Run the existing full dossier generator against an isolated input snapshot.
    # This retains original tables, source ledger and all six detailed appendices.
    with tempfile.TemporaryDirectory(prefix='agro-after-build-') as td:
        stage=Path(td)
        for name in ('docs','data'):shutil.copytree(ROOT/name,stage/name)
        (stage/'docs/FINAL_BUSINESS_PLAN.md').write_text(text)
        summary=json.loads((stage/'data/finance_summary.json').read_text())
        burn=model()[1]['fixed_opex_rub']/12;reserve=model()[0]['reserve_funding_rub']
        summary['cash_runway']['no_revenue_first_negative_month']=next(i for i in range(1,120) if reserve-i*burn<0)
        (stage/'data/finance_summary.json').write_text(json.dumps(summary,ensure_ascii=False))
        old=(word.ROOT,word.OUT,word.ASSETS)
        try:
            word.ROOT=stage;word.OUT=stage/'documents';word.ASSETS=word.OUT/'assets'
            word.main()
        finally:word.ROOT,word.OUT,word.ASSETS=old
        doc=Document(str(stage/'documents/AGROVECTOR_FULL_BUSINESS_PLAN.docx'))
        for p in doc.paragraphs:
            if 'Редакция: 20.10.2026' in p.text:p.text=p.text.replace('Редакция: 20.10.2026','Редакция: после brainstorming; AgroVector_After_brainstorm')
            if p.text.startswith('Ниже сохранен исторический перечень'):
                p.text='Ниже — исторический перечень ограничений, не текущая инвестиционная приемка. Приоритет имеют уточнения разделов 1–22 и Приложение Ж после brainstorming; исходные ссылки/даты сохранены, внешние gates открыты.'
        # Reuse the existing Markdown/table renderer for an explicit new appendix.
        b=word.Builder();b.doc=doc;b.caption=len(doc.tables);b.section_no=22
        doc.add_heading('Приложение Ж. Исправления и устойчивость после brainstorming',level=1)
        b.para('Только документальные исправления и расчетные сценарии. Не подтверждение спроса, допусков, финансирования или полевой производительности. Базовые условия не менялись.')
        body=(ROOT/'docs/FINANCE_CORRECTED_brainstorm.md').read_text()
        b.markdown(body)
        doc.add_heading('Матрица решений по 37 записям риска',level=2)
        b.markdown((ROOT/'docs/CHANGE_DECISIONS_brainstorm.md').read_text())
        out=ROOT/'documents/AGROVECTOR_FULL_BUSINESS_PLAN_brainstorm.docx';doc.save(str(out))
        reopened=Document(str(out))
        headings=[p.text for p in reopened.paragraphs if p.style.name=='Heading 1' and re.match(r'^\d+\.',p.text)]
        assert len(headings)==22,headings
        alltext='\n'.join(p.text for p in reopened.paragraphs)+'\n'+'\n'.join(c.text for t in reopened.tables for r in t.rows for c in r.cells)
        assert '{fmt(' not in alltext
        for tag in ('490 600','21 760','AgroVector_After_brainstorm','Приложение Ж.'):
            assert tag in alltext,tag
        print(json.dumps({'docx':str(out.relative_to(ROOT)),'sections':len(headings),'tables':len(reopened.tables),'diagrams':len(reopened.inline_shapes),'sha256':hashlib.sha256(out.read_bytes()).hexdigest()},ensure_ascii=False))

if __name__=='__main__':
    build_word(build_markdown())
